from pydantic import BaseModel, field_validator

class OrdenCompra(BaseModel):
    codigo_item: str
    cantidad: int

    @field_validator("cantidad")
    @classmethod
    def cantidad_positiva(cls, v: int) -> int:
        if v <= 0:
            raise ValueError("La cantidad debe ser mayor que cero")
        return v
